const NAMES = {1:'Anonymous or fake team',2:'Unlocked liquidity',3:'Unaudited contract or fake audit',4:'Concentrated holdings',5:'Unrealistic yields',6:'No real development activity',7:'Fake partnerships',8:'Hidden mint functions',9:'Brand-new protocol',10:'Low or fake TVL',11:'Opaque treasury',12:'Toxic community and fake urgency'};
const rows = $input.all().map(i => i.json).filter(r => r['Score'] !== undefined && r['Score'] !== '');
const parse = s => { const d = new Date(String(s).replace(',', '')); return isNaN(d) ? null : d; };
const cutoff = Date.now() - 7 * 24 * 3600 * 1000;
const week = rows.filter(r => { const d = parse(r['Received']); return d && d.getTime() >= cutoff; });

function stats(list) {
  const n = list.length;
  if (!n) return null;
  const num = k => list.map(r => Number(r[k]) || 0);
  const avg = a => a.reduce((x, y) => x + y, 0) / a.length;
  const secs = num('Seconds').sort((a, b) => a - b);
  const median = secs.length % 2 ? secs[(secs.length - 1) / 2] : (secs[secs.length / 2 - 1] + secs[secs.length / 2]) / 2;
  const found = num('Flags found');
  const fa = num('False alarms');
  const misses = {};
  for (let f = 1; f <= 12; f++) misses[f] = 0;
  for (const r of list) String(r['Missed flags'] || '').split(',').filter(Boolean).forEach(f => { if (misses[f] !== undefined) misses[f]++; });
  const top = Object.entries(misses).filter(([, c]) => c > 0).sort((a, b) => b[1] - a[1]).slice(0, 3)
    .map(([f, c]) => `#${f} ${NAMES[f]}: missed by ${Math.round(c / n * 100)}% (${c} of ${n})`);
  return {
    n,
    avgFound: avg(found).toFixed(1),
    avgScore: Math.round(avg(num('Score'))),
    avgFalse: avg(fa).toFixed(1),
    medianSecs: Math.round(median),
    all12: found.filter(x => x === 12).length,
    perfect: list.filter(r => Number(r['Flags found']) === 12 && Number(r['False alarms']) === 0).length,
    top
  };
}

const fmt = s => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
const block = (title, s) => !s ? `${title}\nNo games finished.` : [
  title,
  `Games finished: ${s.n}`,
  `Average flags found: ${s.avgFound} of 12`,
  `Average score: ${s.avgScore}`,
  `Average false alarms: ${s.avgFalse}`,
  `Median time: ${fmt(s.medianSecs)}`,
  `Found all 12: ${s.all12} (${Math.round(s.all12 / s.n * 100)}%)`,
  `Perfect games (12 found, 0 false alarms): ${s.perfect}`,
  s.top.length ? `Most missed:\n  ${s.top.join('\n  ')}` : 'Most missed: none, everyone caught everything'
].join('\n');

const w = stats(week), a = stats(rows);
const LESSON = {"1":"Cartoon avatars are not a team. If nobody real is accountable, nobody is.","2":"\"SAFU\" is not a liquidity lock. Find the locker contract yourself.","3":"Anyone can paste an audit badge. Go to the auditor's own site and search for the project.","4":"Check the Holders tab. If a few wallets own most of the supply, they can dump on you.","5":"If nobody deposits tomorrow, where does the yield come from? If no one can say, it's you.","6":"One commit, forked two years ago, is not development. Read the commit history.","7":"A row of logos is not a partnership. Check the partner's own site.","8":"\"Fixed supply, we promise\" means nothing if the contract can mint. Check Read/Write Contract.","9":"\"Get in early\" is the pitch. Most rugs happen in the first weeks. New means unproven.","10":"A big TVL number on a website is just text. Check DefiLlama or DEX Screener.","11":"\"Multisig secured, addresses coming soon\" means you can't see where the money is.","12":"Countdown timers and \"no FUD\" bans exist to stop you from checking. Slow down."};
const chal = week.filter(r => String(r['Source'] || '') === 'challenge').length;
function topMiss(list) {
  const m = {}; for (let f = 1; f <= 12; f++) m[f] = 0;
  for (const r of list) String(r['Missed flags'] || '').split(',').filter(Boolean).forEach(f => { if (m[f] !== undefined) m[f]++; });
  const best = Object.entries(m).sort((x, y) => y[1] - x[1])[0];
  return best && best[1] > 0 ? { f: Number(best[0]), c: best[1] } : null;
}
let drafts = '';
const tm = w ? topMiss(week) : null;
if (tm) {
  const who = tm.c + ' of ' + w.n + ' player' + (w.n === 1 ? '' : 's');
  const x = 'Most-missed red flag at 12redflags.com this week: #' + tm.f + ' ' + NAMES[tm.f] + '. ' + who + ' missed it.\n\n' + LESSON[tm.f] + '\n\nCan you spot all 12? 12redflags.com';
  const fc = 'This week\'s most-missed red flag in the Spot the Flag game: #' + tm.f + ' ' + NAMES[tm.f] + '. ' + who + ' missed it.\n\n' + LESSON[tm.f] + '\n\nThe game is free, takes 3 minutes, and every scam on the page is fake on purpose: 12redflags.com';
  drafts = ['READY TO POST (the Farcaster one is also waiting in the Post Queue tab as a draft; set it to approved to send)', '', 'X (' + x.length + ' of 280 characters):', x, '', 'Farcaster:', fc].join('\n');
}
const subject = w ? `Spot the Flag weekly: ${w.n} games, ${w.avgFound}/12 average` : 'Spot the Flag weekly: no games this week';
const body = [
  block('LAST 7 DAYS', w),
  w ? 'Games from challenge links: ' + chal + ' of ' + w.n : '',
  '',
  block('ALL TIME', a),
  '',
  drafts,
  drafts ? '' : null,
  'Full data: https://docs.google.com/spreadsheets/d/YOUR_GOOGLE_SHEET_ID/edit',
  'Site: https://12redflags.com'
].filter(x => x !== null).join('\n');
const queueText = tm ? ('Most-missed red flag in Spot the Flag this week: #' + tm.f + ' ' + NAMES[tm.f] + '. ' + tm.c + ' of ' + w.n + ' player' + (w.n === 1 ? '' : 's') + ' missed it.\n\n' + LESSON[tm.f] + '\n\nHow many of the 12 can you find?') : null;
return [{ json: { subject, body, queueText } }];

const q = $input.first().json.queueText;
if (!q) return [];
const d = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Los_Angeles' });
return [{ json: { 'ID': 'weekly-' + d, 'Platform': 'farcaster', 'Text': q, 'Link': 'https://12redflags.com/', 'Status': 'draft', 'Notes': 'From the Monday summary. Edit if you like, then set Status to approved.' } }];
